(function(){'use strict';
const D=ArgentumData,A=Argentum,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('es-AR',{maximumFractionDigits:0}).format(n),pct=n=>n.toFixed(1)+'%',btn=(text,action,args={},cls='')=>`<button class="${cls}" data-action="${action}" data-args="${esc(JSON.stringify(args))}">${text}</button>`,card=(html,cls='')=>`<div class="card ${cls}">${html}</div>`,metric=(label,value,note='')=>`<div class="metric"><small>${label}</small><div class="big">${value}</div><small>${note}</small></div>`,bar=(value,color='var(--teal)')=>`<div class="progress"><span style="width:${Math.max(0,Math.min(100,value))}%;background:${color}"></span></div>`,date=day=>{const d=new Date(Date.UTC(2026,0,day));return d.toLocaleDateString('es-AR',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'})};
const online=typeof ArgentumNetwork!=='undefined';
let engine=online?new ArgentumNetwork():new A.Engine(A.newGame('Hernán')),panel=null,tab='projects',started=false,scenario='civil',timer=0,last=0,lastHud=0,toastTimer,returnFocus=null;
const state=()=>engine.state,party=id=>state().politics.parties.find(p=>p.id===id),partyName=id=>esc(party(id)?.name||'Independiente'),color=id=>party(id)?.color||'#bbb',building=id=>D.buildings.find(b=>b.id===id),statusLabels={COMMITTEE:'En comisión',VOTING:'Votación abierta',EXECUTIVE:'A decisión presidencial',ENACTED:'Ley vigente',REJECTED:'Rechazado',VETOED:'Vetado',INVESTIGATION:'Investigación',CHARGED:'Detención fundada',TRIAL:'En juicio',ACQUITTED:'Absuelto',CONVICTED:'Condenado',RELEASED:'Liberado'},votes={YES:'A favor',NO:'En contra',ABSTAIN:'Abstención'};
const world=new ArgentumWorld($('city'),state,id=>{toast('Llegaste a '+building(id).name+'. Presioná E para entrar.');renderHUD()});
function toast(text,error=false){$('toast').textContent=text;$('toast').classList.toggle('error',error);$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);if(state().settings.sound){try{const ctx=audioContext||(audioContext=new(window.AudioContext||window.webkitAudioContext)()),o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=error?180:520;g.gain.setValueAtTime(.025,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.12)}catch{}}}
let audioContext;
function perform(type,args={},success=null){if(online){engine.request(type,args).then(r=>{if(!r.ok){toast(r.error,true);return}if(success)toast(success);if(type==='PROPOSE')tab='projects';if(['ENTER','EXIT','FOOTBALL_START','START'].includes(type)){world.route=[];if(state().session.phase!=='LOBBY'){started=true;close()}}renderHUD();if(panel)renderPanel();});return{ok:false,pending:true};}const before=state().player.inside,r=engine.dispatch(type,args);if(!r.ok){toast(r.error,true);return r}if(success)toast(success);renderHUD();if(state().player.inside!==before&&state().player.legal!=='FREE'){world.route=[];close();toast('Traslado judicial: '+building(state().player.inside)?.name)}else if(panel)renderPanel();return r}
function nearby(){const p=state().player;if(p.inside)return null;return D.buildings.map(b=>({b,d:Math.hypot(p.x-b.x-b.w/2,p.y-b.y-b.h-20)})).filter(x=>x.d<100).sort((a,b)=>a.d-b.d)[0]?.b}
function renderHUD(){const s=state(),p=s.player;$('headerStats').innerHTML=`<div><small>${date(s.time.day).toUpperCase()}</small><strong>Jornada ${s.time.day}</strong></div><div class="cash"><small>TUS ARGENTUMS</small><strong class="gold">₳ ${money(p.money)}</strong></div><div class="optional"><small>APROBACIÓN</small><strong>${pct(s.society.approval)}</strong></div><div class="optional"><small>ELECCIONES EN</small><strong>${s.politics.nextElection-s.time.day} días</strong></div>`;$('actorSelect').disabled=online;if(document.activeElement?.id!=='actorSelect')$('actorSelect').innerHTML=(online?[p]:Object.values(s.players)).map(a=>`<option value="${a.id}" ${a.id===p.id?'selected':''}>${esc(a.name)}${a.isBot?' · bot local':''}</option>`).join('');$('timeControls').innerHTML=(online&&p.id!==s.session.hostId)?'<small>Reloj del servidor</small>':[0,1,2,4].map(n=>btn(n===0?'Ⅱ':n+'×','speed',{speed:n},s.time.speed===n?'selected':'')).join('')+(online?'':btn('+1 día','advance',{days:1}));$('hotbar').innerHTML=D.products.map((prod,i)=>`<button data-action="use" data-args="${esc(JSON.stringify({id:prod.id}))}" title="${esc(prod.name)} · tecla ${i+1}"><span class="key">${i+1}</span>${prod.symbol}<span class="qty">${p.inventory[prod.id]}</span></button>`).join('');const near=nearby(),news=s.news.slice(0,3);$('sidebar').innerHTML=`<section><div class="row"><div class="portrait">${esc(p.name[0].toUpperCase())}</div><div><strong>${esc(p.name)}</strong><br><small>${D.roles[p.role]} · ${p.legal==='FREE'?'Sin restricciones':statusLabels[p.legal]||p.legal}</small></div></div><div class="needs">${[['health','Salud'],['hunger','Alimentación'],['hydration','Hidratación'],['energy','Energía']].map(([k,label])=>`<div><label>${label}<span class="val">${Math.round(p[k])}</span></label>${bar(p[k],p[k]<25?'var(--red)':'var(--teal)')}</div>`).join('')}</div>${btn('Inventario [I]','open',{page:'inventory'},'small')} ${btn('Mi ciudadano','open',{page:'player'},'small')}</section><section>${p.inside?`<div class="context"><small>ESPACIO FÍSICO</small><strong>${esc(building(p.inside)?.name)}</strong><small>${esc(ArgentumInteriors.nearest(s)?.label||'Recorré el interior')}</small><div style="margin-top:8px">${btn('Interactuar [E]','interact',{},'small')} ${btn('Buscar salida','routeexit',{},'small')}</div></div>`:near?`<div class="context"><small>ENTRADA CERCANA</small><strong>${esc(near.name)}</strong>${btn('Entrar [E]','enter',{id:near.id},'primary small')}</div>`:''}<div class="section-title"><h3>Tu primera república</h3><span class="tag">${Object.values(s.goals).filter(Boolean).length}/8</span></div>${[['lobby','Formar partidos de dos personas'],['campaign','Campaña en el mundo'],['election','Elegir Presidente y Juez'],['law','Promulgar una ley'],['purchase','Comprar en la caja'],['football','Jugar con la pelota'],['combat','Impacto y causa judicial'],['justice','Resolver una causa']].map(([k,t])=>`<div class="goal"><span class="check">${s.goals[k]?'✓':'○'}</span>${t}</div>`).join('')}<div class="hint">${!s.goals.election?'Primero campaña: acto en la plaza o debate en el Congreso. Consultá las fechas de apertura de urnas y escrutinio en Elecciones.':!s.goals.law?'Recorré el Congreso hasta el atril. Presentá una ley y construí una mayoría.':'Las leyes afectan a todos. Negociá, comerciá y prepará la próxima elección.'}</div></section><section class="news-section"><div class="section-title"><h3>La voz del Plata</h3>${btn('Ver todas','open',{page:'news'},'small')}</div>${news.map(n=>`<div class="news-item"><small>JORNADA ${n.day} · ${esc(n.category.toUpperCase())}</small><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p></div>`).join('')}</section>`;
 $('destination').hidden=!world.route.length;$('destination').textContent=world.target?'Caminando a '+building(world.target).name:'Recorriendo el barrio';$('worldInstruction').textContent=p.legal!=='FREE'?'Proceso judicial activo · avanzá días para continuar':p.inside?'WASD caminar · SHIFT correr · E interactuar · puerta física para salir':'WASD caminar · SHIFT correr · E interactuar · I inventario';$('footerStatus').textContent=online?engine.status+(engine.latency!==null?' · '+engine.latency+' ms':'')+' · reloj compartido':s.time.speed&&panel?'Tiempo pausado durante la consulta':s.time.speed?'Un día cada '+(12/s.time.speed)+' segundos':'Tiempo en pausa · avanzá cuando quieras';
}
function open(page){returnFocus=document.activeElement;panel=page;tab='projects';world.keys.clear();renderPanel();$('overlay').classList.add('open');$('overlay').querySelector('button').focus()}
function close(){if(panel==='welcome'&&!started)return;panel=null;$('overlay').classList.remove('open');returnFocus?.focus?.();renderHUD()}
function setBody(title,eyebrow,body,note=online?'Partida compartida: el mundo sigue activo mientras consultás.':'El tiempo se pausa al abrir un panel. Podés avanzar días con los controles de esta pantalla.'){$('dialogTitle').textContent=title;$('dialogEyebrow').textContent=eyebrow;$('dialogBody').innerHTML=body;$('dialogNote').textContent=note;$('overlay').classList.add('open')}
function access(id){const s=state();return s.player.inside===id&&s.player.legal==='FREE'&&ArgentumInteriors.get(id).objects.some(o=>['congress','executive','justice','market','property'].includes(o.kind)&&ArgentumInteriors.near(s.player,o))}
function needVisit(id){return access(id)?'':`<div class="message">Podés consultar desde el teléfono. Para actuar, acercate a ${esc(building(id).name)}. ${btn('Ir caminando','goto',{id},'small')}</div>`}
function tabs(items){return `<div class="dialog-tabs">${items.map(([id,label])=>btn(label,'tab',{tab:id},tab===id?'active':'')).join('')}</div>`}
function spark(key,color='#7cc4bb'){const h=state().economy.history;if(h.length<2)return '<div class="empty">Avanzá dos días para observar la tendencia.</div>';const values=h.map(x=>x[key]),min=Math.min(...values),max=Math.max(...values),range=max-min||1;return `<svg class="chart" viewBox="0 0 500 110" preserveAspectRatio="none" aria-label="Evolución de ${key}"><path d="M 0 100 H 500 M 0 50 H 500" stroke="#40555a" stroke-width=".5"/><polyline points="${values.map((v,i)=>`${i/(values.length-1)*500},${95-(v-min)/range*80}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg><div class="spark-labels"><span>Día ${h[0].day} · ${values[0].toFixed(1)}</span><span>Día ${h.at(-1).day} · ${values.at(-1).toFixed(1)}</span></div>`}
function congress(){const s=state(),ps=s.politics,can=access('congress');if(!ps.president.id){setBody('El Congreso durante la campaña','RECINTO ABIERTO · BANCAS TODAVÍA SIN ASIGNAR',`<p>Podés recorrer el recinto, participar del debate junto al micrófono del hall y votar en la urna cuando abra. El Congreso se constituye después de la elección.</p>${btn('Ver campaña','open',{page:'politics'},'primary')} ${btn('Volver al recinto','close')}`);return}let body=needVisit('congress')+tabs([['projects','Proyectos y leyes'],['chamber','Las '+s.session.seatCount+' bancas'],['new','Presentar proyecto']]);if(tab==='new'){body+=card(`<h3>Una propuesta que modifica la ciudad</h3><p>Cualquier ciudadano puede presentar una iniciativa. Los legisladores evalúan su contenido durante dos días; luego votan. El Presidente promulga o veta.</p><label>Nombre del proyecto</label><input id="billTitle" maxlength="80" value="Reforma del impuesto al consumo"><div class="grid" style="margin-top:15px"><div><label>Instrumento</label><select id="lawKey">${Object.entries(D.laws).map(([id,l])=>`<option value="${id}">${l.name}</option>`).join('')}</select></div><div><label id="valueLabel">Nueva tasa · 5 a 35 %</label><input id="lawValue" type="number" min="5" max="35" value="25" step="1"></div></div><p id="lawDescription" style="margin-top:12px">${D.laws.tax.description}</p><div class="row between"><span class="muted">Actual: <span id="currentValue">${money(s.policy.tax*100)}%</span></span>${can?btn('Presentar en comisión','propose',{},'primary'):btn('Ir al Congreso','goto',{id:'congress'},'primary')}</div>`);}
 else if(tab==='chamber'){body+=`<div class="grid">${card(`<h3>Cámara de Representantes</h3><div class="seats">${ps.legislators.map(l=>`<span class="seat" style="background:${color(l.party)}" title="${esc(l.name)} · ${partyName(l.party)}"></span>`).join('')}</div><p>${s.session.seatCount} bancas · quórum de ${Math.floor(s.session.seatCount/2)+1} presentes. Ley ordinaria: más votos a favor que en contra. Insistencia sobre un veto: ${Math.ceil(s.session.seatCount*2/3)} votos.</p>`)}${card(`<h3>Poder Ejecutivo</h3><div class="big">${esc(ps.president.name)}</div><p>${partyName(ps.president.party)} · mandato consecutivo ${ps.president.terms}</p><small>Próxima renovación: ${date(ps.nextElection)}. El Ejecutivo no modifica impuestos directamente.</small>`)}</div><table><thead><tr><th>Legislador</th><th>Bloque</th><th>Distrito</th></tr></thead><tbody>${ps.legislators.map(l=>`<tr><td>${esc(l.name)}${l.id==='player'?' · VOS':''}</td><td><i class="party-dot" style="background:${color(l.party)}"></i>${partyName(l.party)}</td><td>${l.district}</td></tr>`).join('')}</tbody></table>`;}
 else{body+=`<div class="row between" style="margin-bottom:15px"><p class="muted">El contenido consigue los votos. Modificá la propuesta para construir acuerdos.</p>${btn('＋ Nuevo proyecto','tab',{tab:'new'},'primary')}</div>`;if(!ps.bills.length)body+=`<div class="empty">La agenda está abierta. Presentá tu primera propuesta.</div>`;for(const b of ps.bills){const pred=A.predicted(s,b),result=b.result;body+=card(`<div class="row between"><span class="law-status">${statusLabels[b.status]}</span><small>EXP. ${b.id} · versión ${b.revision||1} · día ${b.created}</small></div><h3 style="margin-top:8px">${esc(b.title)}</h3><p>${D.laws[b.key].name}: <strong class="gold">${money(b.value*D.laws[b.key].factor)}${D.laws[b.key].unit}</strong>${b.packageHealth?' + presupuesto sanitario '+Math.round(b.packageHealth*100)+'%':''}</p><div class="chain">${['COMMITTEE','VOTING','EXECUTIVE','ENACTED'].map((st,i)=>`<span class="${['COMMITTEE','VOTING','EXECUTIVE','ENACTED'].indexOf(b.status)>=i?'on':''}">${['Comisión','Votación','Presidencia','Vigencia'][i]}</span>`).join('')}</div>${result?`<div class="row wrap"><span class="teal">${result.yes} a favor</span><span>${result.no} en contra</span><span class="muted">${result.abstain} abstenciones</span><span class="tag">${result.quorum?'CON QUÓRUM':'SIN QUÓRUM'}</span></div>`:`<small>Votación desde el día ${b.voteDay}. Posiciones estimadas según el texto actual:</small><div class="row wrap" style="margin-top:7px">${ps.parties.map(p=>{const ls=pred.filter(l=>l.party===p.id);return `<span style="color:${p.color};font-size:12px">${p.short}: ${ls.filter(v=>v.vote==='YES').length}/${ls.length} a favor</span>`}).join('')}</div>`}
 ${b.status==='COMMITTEE'?`<details><summary>Negociar el contenido con los bloques</summary><p>Los bloques no venden votos. Evaluá sus preferencias y ofrecé un texto compatible; sumar salud también aumenta el gasto.</p><table><tr><th>Bloque</th><th>Preferencia</th><th>Propuesta</th></tr>${ps.parties.map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p[b.key]*D.laws[b.key].factor)}${D.laws[b.key].unit}</td><td>${can?btn('Acercar texto','compromise',{id:b.id,party:p.id},'small'):''}</td></tr>`).join('')}</table><div class="row wrap" style="margin-top:12px"><label>Nuevo valor <input id="amend-${b.id}" type="number" min="${D.laws[b.key].min}" max="${D.laws[b.key].max}" value="${b.value*D.laws[b.key].factor}"></label>${can?btn('Actualizar texto','amend',{id:b.id},'small'):''}${can&&b.key!=='health'?btn(b.packageHealth?'Retirar artículo sanitario':'Agregar salud al 120%','package',{id:b.id},'small'):''}</div></details>`:''}
 <div class="actions">${b.status==='COMMITTEE'&&can?['YES','NO','ABSTAIN'].map(v=>btn('Mi bloque: '+votes[v],'command',{type:'BLOCK_STANCE',args:{id:b.id,vote:v}},'small')).join(''):''}${b.status==='COMMITTEE'?btn('Avanzar hasta la votación','advance',{days:Math.max(1,b.voteDay-s.time.day)},'small'):''}${b.status==='VOTING'&&s.player.role==='LEGISLATOR'&&can?Object.entries(votes).map(([vote,t])=>btn(t,'command',{type:'VOTE',args:{id:b.id,vote}},'small')).join(''):''}${b.status==='EXECUTIVE'?(ps.president.id===s.player.id?can?btn('Promulgar','command',{type:'EXECUTIVE',args:{id:b.id}},'primary')+btn('Vetar','command',{type:'EXECUTIVE',args:{id:b.id,veto:true}},'danger'):'':btn('Esperar decisión · 1 día','advance',{days:1},'small')):''}${b.status==='VETOED'&&can?btn('Solicitar insistencia · ⅔','command',{type:'OVERRIDE',args:{id:b.id}},'small'):''}</div>${b.votes.length?`<details><summary>Acta nominal de votación</summary><table><tr><th>Legislador</th><th>Bloque</th><th>Voto</th></tr>${b.votes.map(v=>`<tr><td>${esc(v.name)}</td><td>${partyName(v.party)}</td><td>${votes[v.vote]}</td></tr>`).join('')}</table></details>`:''}${b.versions?.length?`<details><summary>Versiones del texto</summary>${b.versions.map(v=>`<p>Versión ${v.revision} · día ${v.day}: ${money(v.value*D.laws[b.key].factor)}${D.laws[b.key].unit}${v.packageHealth?' · salud '+money(v.packageHealth*100)+'%':''}</p>`).join('')}</details>`:''}${b.reason?`<small>${esc(b.reason)}</small>`:''}`,'bill');}}
 setBody('El Congreso','INSTITUCIONES · EL PODER DE LOS ACUERDOS',body);
}
function economy(){const s=state(),e=s.economy;setBody('La economía de la República','CADA TRANSACCIÓN TIENE UNA CONTRAPARTE',`<div class="grid three">${card(metric('Actividad',e.activity.toFixed(1),'Índice · base 100'))}${card(metric('Inflación',pct(e.inflation),'Ritmo mensual simulado'))}${card(metric('Empleo',pct(e.employment),'De la población activa'))}${card(metric('Tesoro nacional','₳ '+money(s.accounts.treasury),'Saldo disponible'))}${card(metric('Balance del día','₳ '+money(e.balance),'Ingresos menos gastos'))}${card(metric('Deuda pública','₳ '+money(e.debt),'Interés mensual: 2,5%'))}</div><div class="grid" style="margin-top:15px">${card(`<h3>Actividad económica</h3>${spark('activity')}`)}${card(`<h3>Precio de una vianda</h3>${spark('price','#d8bc7d')}`)}</div><div class="grid" style="margin-top:15px">${card(`<h3>Cuentas del Estado · jornada ${s.time.day}</h3><table><tr><td>Ingresos</td><td>₳ ${money(e.revenue)}</td></tr><tr><td>Gastos</td><td>₳ ${money(e.spending)}</td></tr><tr><td>Salud · ${s.policy.health*100}%</td><td>₳ ${money(5200*s.policy.health)} / día</td></tr><tr><td>Seguridad · ${s.policy.security*100}%</td><td>₳ ${money(3900*s.policy.security)} / día</td></tr><tr><td>Servicios e intereses</td><td>₳ ${money(3400+e.debt*e.interest/30)} / día</td></tr></table><small>La deuda financia faltantes de caja; no cuenta como recaudación.</small>`)}${card(`<h3>Cómo se transmite una ley</h3><p>Un impuesto mayor cambia el precio final de inmediato. La demanda, la confianza y la actividad se adaptan gradualmente. El gasto sanitario mejora la capacidad del hospital y consume recursos del Tesoro.</p><p>La inflación mensual responde al balance fiscal y a la actividad. No es un modelo econométrico: son reglas de juego visibles y comparables.</p><small>Consumo agregado hoy: ₳ ${money(e.consumption)} · confianza: ${e.confidence.toFixed(1)} · pobreza: ${pct(e.poverty)}</small>`)}</div><div class="section-title"><h3>Canasta de productos · impuesto ${money(s.policy.tax*100)}%</h3>${btn('Ir al mercado','goto',{id:'market'},'small')}</div><table><tr><th>Producto</th><th>Stock</th><th>Precio final</th></tr>${D.products.map(p=>`<tr><td>${p.symbol} ${p.name}</td><td>${s.world.stock.market[p.id]}</td><td>₳ ${money(A.price(s,p.id))}</td></tr>`).join('')}</table><details><summary>Libro de transacciones · últimas 50</summary>${ledgerTable(s.ledger.slice(0,50))}</details><div class="row wrap" style="margin-top:18px">${btn('Avanzar 1 día','advance',{days:1})}${btn('Observar 7 días','advance',{days:7},'primary')}</div>`)}
function ledgerTable(items){return `<table><tr><th>Día</th><th>Concepto</th><th>Origen → destino</th><th>Argentums</th></tr>${items.map(t=>`<tr><td>${t.day}</td><td>${esc(t.reason)}</td><td>${esc(t.from)} → ${esc(t.to)}</td><td>${money(t.amount)}</td></tr>`).join('')}</table>`}
function society(){const s=state();setBody('El pulso de la sociedad','SIETE SECTORES · PRIORIDADES DIFERENTES',`<div class="grid">${card(metric('Aprobación del gobierno',pct(s.society.approval),'Agregada según el peso de cada sector')+spark('approval'))}${card(`<h3>Demandas de la ciudad</h3><p>El empleo, los precios, los servicios y la seguridad afectan de forma diferente a cada grupo. Las preferencias políticas son multidimensionales.</p><div class="big">${s.society.protest?'Manifestación activa':'Actividad habitual'}</div><small>${s.society.protest?'Hay una protesta en la plaza.':'Sin protestas activas. Umbral de movilización: aprobación menor al 42%.'}</small>`)}</div><div class="grid" style="margin-top:15px">${s.society.sectors.map(g=>card(`<div class="row between"><h3>${g.name}</h3><span>${pct(g.satisfaction)}</span></div>${bar(g.satisfaction)}<small>${g.weight*100}% de la población · prioridad principal: ${['empleo y precios','salud y servicios','seguridad','confianza'][g.priorities.indexOf(Math.max(...g.priorities))]}</small>`)).join('')}</div><div style="margin-top:15px">${btn('Observar 7 días','advance',{days:7},'primary')}</div>`)}
function politics(){const s=state(),ps=s.politics;let content=tabs([['projects','Elección y encuestas'],['parties','Partidos'],['create','Reglas de la fórmula']]);if(tab==='create'){content+=card(`<h3>Una fórmula, dos personas</h3><p>Los partidos quedaron constituidos en el lobby. Cada uno tiene exactamente un candidato presidencial y un candidato judicial. No se agregan miembros durante la partida.</p><p>La fórmula ganadora ocupa ambos cargos, con facultades independientes. El Congreso recibe bancas proporcionales al resultado.</p><small>${online?'Modo online: cada conexión controla su ciudadano. Bots disponibles solo en salas de prueba.':'Modo local de prueba: control alternado y bots.'}</small>`)}else if(tab==='parties'){content+=`<div class="grid">${ps.parties.map(p=>card(`<span class="tag" style="color:${p.color}">${p.short}</span><h3 style="margin-top:9px">${esc(p.name)}</h3><p>${esc(p.platform)}</p><small>Presidente: ${esc(s.players[p.candidates.president]?.name)}<br>Juez: ${esc(s.players[p.candidates.judge]?.name)}<br>Integrantes: ${p.members.length}/2</small><hr><small>Consumo preferido ${money(p.tax*100)}% · salud ${money(p.health*100)}% · seguridad ${money(p.security*100)}%</small><div style="margin-top:13px">${s.player.party===p.id?'<span class="teal">Tu partido</span>':'<small>Oposición / otra fórmula</small>'}</div>`)).join('')}</div>`}else{content+=`<div class="grid">${card(metric('Próxima elección',date(ps.nextElection),(ps.nextElection-s.time.day)+' días · padrón de 10.000 votantes')+`<hr><p>Fase: <strong>${{CAMPAIGN:'Campaña',BALLOT:'Votación',GOVERNMENT:'Gobierno'}[s.session.phase]}</strong><br>Presidente: ${esc(ps.president.name)}<br>Juez: ${esc(ps.judge.name)}</p><div class="row wrap">${btn('Avanzar 7 días','advance',{days:7})}${btn(s.session.phase==='BALLOT'?'Cerrar escrutinio':'Abrir urnas','advance',{days:Math.max(1,(s.session.phase==='BALLOT'?ps.nextElection:ps.nextElection-s.session.ballotDays)-s.time.day)},'primary')}</div>`)}${card(`<h3>Tu campaña</h3><p>${s.player.party?'Participás de '+partyName(s.player.party)+'.':'Todavía no tenés afiliación. Podés sumarte a un partido o crear uno.'}</p><small>Alcance acumulado: ${ps.campaign[s.player.party]||0}/45. Una acción al día, con costo real. La campaña ayuda, pero no garantiza votos.</small><div style="margin-top:15px">${btn('Ir al acto en la plaza','goto',{id:'plaza'},'primary')} ${btn('Participar aquí · ₳ 1.500','command',{type:'CAMPAIGN'},'small')}</div>`)}</div><div class="section-title"><h3>Encuesta · Instituto del Plata</h3><small>${ps.poll?'Día '+ps.poll.day+' · margen ±3 puntos':'Primera encuesta: día 7'}</small></div>${ps.poll?card(ps.poll.values.map(r=>`<div class="row between"><span><i class="party-dot" style="background:${color(r.party)}"></i>${partyName(r.party)}</span><strong>${pct(r.value)}</strong></div>${bar(r.value,color(r.party))}`).join('')+'<small>Estimación muestral. No revela el escrutinio futuro.</small>'):'<div class="empty">Todavía no hay una encuesta publicada.</div>'}<div class="section-title"><h3>Resultados y transiciones</h3></div>${ps.elections.map(e=>card(`<h3>Elección del día ${e.day}</h3><p>Asumió ${esc(e.president)}. Juez: ${esc(e.judge)}. Abstenciones de participantes: ${e.abstentions}.</p><table><tr><th>Partido</th><th>Votos</th><th>Porcentaje</th><th>Bancas</th></tr>${e.results.map(r=>`<tr><td>${partyName(r.party)}</td><td>${money(r.votes)}</td><td>${pct(r.share)}</td><td>${e.seats.find(q=>q.party===r.party).count}</td></tr>`).join('')}</table>`)).join('')||'<div class="empty">La primera elección todavía no ocurrió.</div>'}`}
setBody('La próxima mayoría','ELECCIONES · CAMPAÑA · TRANSICIÓN',content)}
function laws(){const s=state(),c=s.politics.constitution;setBody('Las reglas de la República','CONSTITUCIÓN Y LEYES VIGENTES',`<div class="grid">${card(`<h3>Constitución de Argentum</h3><p>República representativa. Toda persona puede presentar iniciativas. El Congreso legisla; el Ejecutivo promulga o veta. La justicia exige evidencia y limita las condenas.</p><table><tr><td>Duración del mandato</td><td>${c.termLength} días</td></tr><tr><td>Máximo de mandatos consecutivos</td><td>${c.maxTerms}</td></tr><tr><td>Cámara de Representantes</td><td>${s.session.seatCount} bancas</td></tr><tr><td>Quórum</td><td>${Math.floor(s.session.seatCount*c.quorum)+1} presentes</td></tr><tr><td>Insistencia sobre veto</td><td>${Math.ceil(s.session.seatCount*2/3)} votos</td></tr></table><small>La reforma constitucional no está habilitada en esta edición. Las reglas superiores no se cambian con una ley ordinaria.</small>`)}${card(`<h3>Marco vigente</h3>${Object.entries(D.laws).map(([id,l])=>`<div class="row between" style="margin:12px 0"><span>${l.name}</span><strong class="gold">${money(s.policy[id]*l.factor)}${l.unit}</strong></div>`).join('')}<hr><small>Ingresos personales: 10%. Tasa inmobiliaria diaria: 0,02%. Estos dos tributos son fijos en esta edición.</small>`)}</div><div class="section-title"><h3>Leyes promulgadas</h3></div>${s.politics.laws.map(l=>card(`<span class="tag">VIGENTE DESDE EL DÍA ${l.effectiveDate}</span><h3 style="margin-top:12px">${esc(l.title)}</h3><p>${D.laws[l.key].name}: ${money(l.value*D.laws[l.key].factor)}${D.laws[l.key].unit}.</p>`)).join('')||'<div class="empty">Todavía no hay leyes nuevas. Rige el marco inicial.</div>'}`)}
function inventory(){const s=state();setBody('Tus pertenencias','INVENTARIO · CINCO ACCESOS RÁPIDOS',`<p class="muted">Las teclas 1–5 consumen el producto correspondiente. El extintor se utiliza en un incendio con rol de bombero.</p>${D.products.map(p=>`<div class="product"><div class="symbol">${p.symbol}</div><div class="info"><strong>${p.name}</strong><small>${p.id==='extinguisher'?'Tres cargas por unidad':Object.entries({health:'salud',hunger:'alimentación',hydration:'hidratación',energy:'energía'}).filter(([key])=>p[key]).map(([key,label])=>'+'+p[key]+' '+label).join(' · ')}</small></div><strong>× ${s.player.inventory[p.id]}</strong>${p.id==='extinguisher'?'':btn('Usar','use',{id:p.id},'small')}${btn('Dejar','command',{type:'DROP',args:{id:p.id}},'small')}</div>`).join('')}<div class="section-title"><h3>Equipo de prueba</h3></div><p class="muted">Retirá un equipo en el armario físico de la comisaría. Clic apunta y dispara; R recarga. Los impactos generan daño y causa judicial.</p><div class="row wrap">${btn('Equipar pistola · '+(s.player.inventory.pistol||0),'equip',{id:'pistol'},'small')}${btn('Equipar arma corta · '+(s.player.inventory.knife||0),'equip',{id:'knife'},'small')}${btn('Guardar arma','equip',{id:null},'small')}</div><p style="margin-top:10px">Cargador: ${s.player.ammo.magazine}/6 · reserva: ${s.player.ammo.reserve} · equipado: ${s.player.equipped||'ninguno'}.</p><div class="section-title"><h3>Objetos cercanos</h3></div>${s.drops.filter(d=>d.inside===s.player.inside&&Math.hypot(d.x-s.player.x,d.y-s.player.y)<60).map(d=>`<div class="row between">${D.products.find(p=>p.id===d.product).name}${btn('Recoger','command',{type:'PICKUP',args:{id:d.id}},'small')}</div>`).join('')||'<small>No hay objetos en el suelo a tu alcance.</small>'}`)}
function interior(b){const color=b.color;return `<div class="interior"><svg viewBox="0 0 950 180" role="img" aria-label="Interior de ${esc(b.name)}"><defs><pattern id="tile" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#ffffff0c"/></pattern></defs><rect width="950" height="180" fill="#2f4543"/><rect width="950" height="65" fill="${color}"/><path d="M0 65H950" stroke="#d7c8a2" stroke-width="5"/><rect y="65" width="950" height="115" fill="url(#tile)"/>${Array.from({length:5},(_,i)=>`<rect x="${75+i*170}" y="13" width="72" height="40" fill="#466b68" stroke="#d3c9aa" stroke-width="5"/><path d="M${111+i*170} 13V53" stroke="#c8c8aa" stroke-width="3"/>`).join('')}<path d="M40 125L300 100H640L905 125V148H40Z" fill="#927f5a"/><rect x="65" y="129" width="815" height="19" fill="#625b45"/><rect x="430" y="103" width="92" height="27" rx="4" fill="#304f51"/><text x="476" y="122" fill="#dbc998" text-anchor="middle" font-family="Georgia" font-size="13">${esc(b.short)}</text><circle cx="370" cy="89" r="9" fill="#d1b591"/><path d="M356 103Q370 91 384 103V119H356" fill="#617c86"/><circle cx="590" cy="89" r="9" fill="#c6a987"/><path d="M576 103Q590 91 604 103V119H576" fill="#9f8261"/></svg></div>`}
function jobUI(id){const s=state();return Object.entries(D.jobs).filter(([key,job])=>job.at===id&&key!=='judge').map(([key,job])=>card(`<div class="row between"><div><h3>${job.name}</h3><small>Salario bruto: ₳ ${money(job.pay)} · un turno por día</small></div></div><div class="row wrap" style="margin-top:12px">${s.player.job===key?btn('Cumplir turno','command',{type:'WORK'},'primary'):key==='employee'||s.player.training.includes(key)?btn('Tomar empleo','command',{type:'JOB',args:{job:key}},'small'):btn('Capacitarme · ₳ 1.200 + 1 día','command',{type:'TRAIN',args:{job:key}},'small')}</div>`)).join('')}
function buildingPanel(){const s=state(),p=s.player,b=building(p.inside);if(!b){panel='map';renderPanel();return}if(b.kind==='congress'){congress();return}let body=`<div class="row between" style="margin-bottom:18px"><small>INTERIOR · ${esc(b.name)}</small>${btn('Volver al espacio físico','close',{},'small')}</div>`;
 if(b.kind==='market'){body+=card(`<h3>Tu carrito</h3>${Object.entries(p.cart).filter(([,q])=>q).map(([id,q])=>`<p>${D.products.find(p=>p.id===id).name} × ${q} · ₳ ${money(A.price(s,id)*q)}</p>`).join('')||'<p>Vacío. Recorré las góndolas y usá E para tomar productos.</p>'}${btn('Pagar carrito','command',{type:'CHECKOUT'},'primary')} ${btn('Vaciar carrito','command',{type:'CART_CLEAR'},'small')}`);body+=`<p class="muted">Precios finales con impuesto al consumo del ${money(s.policy.tax*100)}%. Cada compra descuenta stock, acredita al comercio y recauda para el Estado.</p>${D.products.map(item=>`<div class="product"><div class="symbol">${item.symbol}</div><div class="info"><strong>${item.name}</strong><small>Estante: ${s.world.stock.market[item.id]} · en tu mochila: ${p.inventory[item.id]}</small></div><strong>₳ ${money(A.price(s,item.id))}</strong><small>Tomá productos en la góndola [E]</small></div>`).join('')}<div class="section-title"><h3>Trabajá en el mercado</h3></div>${jobUI(b.id)}<details><summary class="danger">Acción delictiva</summary><p>La caja tiene cámaras. Un robo inicia una investigación, detención y juicio; no es dinero gratuito.</p>${btn('Robar ₳ 1.500','command',{type:'CRIME',args:{crime:'theft'}},'danger')}</details>`}
 if(b.kind==='hospital')body+=`<div class="grid">${card(metric('Capacidad sanitaria',Math.round(s.economy.healthQuality)+'/100','Depende del presupuesto aprobado')+`<hr><p>Tu salud: ${Math.round(p.health)}/100. La atención recupera salud según la capacidad del hospital.</p>${btn('Recibir atención · ₳ 350','command',{type:'TREAT'},'primary')}`)}${card(`<h3>Trabajar en salud</h3><p>Capacitación simplificada de un día de juego. Los salarios se pagan con el Tesoro, sujetos a disponibilidad.</p>`)}</div><div class="grid" style="margin-top:15px">${jobUI(b.id)}</div>`;
 if(b.kind==='police'||b.kind==='court'||b.kind==='jail'){const active=s.justice.cases.filter(c=>['CHARGED','TRIAL','CONVICTED'].includes(c.status));body+=`<div class="hint">${b.kind==='police'?'El registro policial muestra solamente personas detenidas actualmente. Cada detención requiere una causa.':b.kind==='court'?'La investigación reúne evidencia; el tribunal decide. El umbral para condenar es 60% de evidencia y no existe condena retroactiva.':'Las puertas ocupadas están bloqueadas. No podés salir ni moverte mientras cumplís una condena.'}</div><div class="section-title"><h3>${b.kind==='court'?'Expedientes':'Detenidos actuales'}</h3>${btn('Avanzar 1 día','advance',{days:1},'primary')}</div>${(b.kind==='court'?s.justice.cases:active).map(c=>card(`<span class="tag">${statusLabels[c.status]}</span><h3 style="margin-top:10px">Caso ${c.id} · ${s.players[c.suspect]?esc(s.players[c.suspect].name):esc(c.suspect)}</h3><p>${esc(c.reason)}. Evidencia: ${Math.round(c.evidence*100)}%.</p>${c.releaseDay?`<small>Condena: ${c.sentence} días · libertad prevista: día ${c.releaseDay}</small>`:''}${p.role==='JUDGE'&&c.status==='TRIAL'?`<div class="row">${btn('Condenar','command',{type:'VERDICT',args:{id:c.id,decision:'CONVICT'}},'small')}${btn('Absolver','command',{type:'VERDICT',args:{id:c.id,decision:'ACQUIT'}},'small')}</div>`:''}`,'case')).join('')||'<div class="empty">NO HAY DETENIDOS ACTUALMENTE.</div>'}`;if(b.kind==='police'&&p.role==='POLICE')body+=`<div class="section-title"><h3>Investigaciones abiertas</h3></div>${s.justice.cases.filter(c=>c.status==='INVESTIGATION').map(c=>card(`<h3>Caso ${c.id}</h3><p>${esc(c.suspect)} · ${esc(c.reason)} · evidencia ${Math.round(c.evidence*100)}%.</p>${btn('Detener con causa registrada','command',{type:'ARREST',args:{id:c.id}},'small')}`)).join('')||'<small>No hay investigaciones abiertas.</small>'}`;if(b.kind==='jail')body+=`<div class="grid" style="margin-top:15px">${s.justice.cells.map(c=>`<div class="cell"><strong>CELDA ${c.cellId}</strong><small>${c.locked?'PUERTA BLOQUEADA':'PUERTA ABIERTA'} · ${c.occupantPlayerId?'Ocupada':'Libre'}</small></div>`).join('')}</div>`;body+=`<div style="margin-top:15px">${jobUI(b.id)}</div>`}
 if(b.kind==='fire')body+=jobUI(b.id)+`<div class="section-title"><h3>Emergencias activas</h3></div>${s.events.filter(e=>e.status==='ACTIVE').map(e=>card(`<h3>Incendio en ${e.location}</h3><p>Falla eléctrica. Se requieren ${e.intensity} cargas de extintor. Comprá el equipo en el mercado y acercate al lugar.</p>${btn('Ir al incidente','goto',{id:e.location},'primary')}`)).join('')||'<div class="empty">No hay emergencias activas.</div>'}`;
 if(b.kind==='plaza')body+=`<div class="grid">${card(`<h3>Un respiro en el barrio</h3><p>Descansar recupera 20 puntos de energía y avanza un día. En una casa propia, el descanso recupera 60.</p>${btn('Descansar · 1 día','command',{type:'REST'},'primary')}`)}${card(`<h3>La plaza también es política</h3><p>${s.society.protest?'Hay una manifestación por las condiciones de vida.':'Vecinos, comerciantes y trabajadores comparten la plaza.'}</p>${btn('Ver demandas','open',{page:'society'},'small')} ${btn('Campaña','open',{page:'politics'},'small')}`)}</div>`;
 if(b.kind==='pitch'){footballPanel();return}if(false)body+=card(`<h3>Fútbol de barrio</h3><p>Un encuentro social sin minijuego de pelota: recuperás 7 puntos de salud, ganás 2 de reputación y gastás 15 de energía. Se puede jugar una vez al día.</p>${btn('Jugar con los vecinos · ₳ 450','command',{type:'FOOTBALL'},'primary')}`);
 if(b.kind==='property')body+=propertyUI(b);
 const emergency=s.events.find(e=>e.location===b.id&&e.status==='ACTIVE');if(emergency)body+=card(`<h3>Incendio activo · ${emergency.intensity} cargas restantes</h3><p>Requiere rol de bombero y extintor con carga.</p>${btn('Descargar extintor','command',{type:'FIRE',args:{id:emergency.id}},'danger')}`);
 setBody(b.name,'VIDA EN LA CIUDAD',body);
}
function propertyUI(b){const s=state(),prop=s.world.properties[b.id],owned=prop.ownerId===s.player.id;if(!owned)return card(`<span class="tag">CASA + LOCAL · ${b.id}</span><h3 style="margin-top:12px">Tu lugar en ${b.id[0]==='N'?'Barrio Norte':'Barrio Sur'}</h3><p>Incluye vivienda, depósito y negocio. Podés descansar, guardar objetos, comprar stock y vender a la población.</p><div class="big">₳ ${money(prop.price)}</div><small>Tasa inmobiliaria diaria: ₳ ${money(prop.value*s.policy.property)}.</small><div style="margin-top:15px">${btn('Comprar propiedad','command',{type:'BUY_PROPERTY',args:{id:b.id}},'primary')}</div>`);
 return `<div class="grid">${card(`<h3>Tu casa</h3><p>${b.id} · escritura a nombre de ${esc(s.player.name)}.</p>${btn('Descansar · 1 día','command',{type:'REST'},'primary')}<hr><small>Venta al registro: ₳ ${money(prop.value*.9)}. Requiere retirar todos los bienes.</small><div style="margin-top:10px">${btn('Vender propiedad','command',{type:'SELL_PROPERTY',args:{id:b.id}},'small')}</div>`)}${card(`<h3>Administrar el negocio</h3><p>Estado: ${prop.open?'ABIERTO':'CERRADO'} · caja: ₳ ${money(s.accounts[b.id])}</p><label>Multiplicador de precio base · 0,8 a 2</label><input id="markup" type="number" min="0.8" max="2" step="0.05" value="${prop.markup}"><div class="row wrap" style="margin-top:12px">${btn(prop.open?'Cerrar local':'Abrir local','business',{id:b.id,open:!prop.open},'primary')}${btn('Aplicar precio','business',{id:b.id,open:prop.open},'small')}${btn('Retirar caja','command',{type:'WITHDRAW',args:{id:b.id}},'small')}</div>`)}</div><div class="section-title"><h3>Stock del local</h3><small>Ventas según precio y demanda al avanzar días.</small></div>${D.products.map(item=>`<div class="product"><div class="symbol">${item.symbol}</div><div class="info"><strong>${item.name}</strong><small>Stock: ${s.world.stock[b.id][item.id]} · venta: ₳ ${money(A.price(s,item.id,b.id))} · proveedor ×5: ₳ ${money(item.base*.65*s.economy.priceIndex*5)}</small></div>${btn('Reponer ×5','command',{type:'RESTOCK',args:{store:b.id,id:item.id,quantity:5}},'small')}${btn('Retirar 1','command',{type:'TAKE_STOCK',args:{store:b.id,id:item.id}},'small')}</div>`).join('')}<details><summary>Depósito de la casa</summary>${D.products.map(item=>`<div class="product"><div class="info"><strong>${item.name}</strong><small>Mochila: ${s.player.inventory[item.id]} · depósito: ${prop.storage[item.id]}</small></div>${btn('Guardar 1','command',{type:'STORAGE',args:{store:b.id,id:item.id}},'small')}${btn('Retirar 1','command',{type:'STORAGE',args:{store:b.id,id:item.id,take:true}},'small')}</div>`).join('')}</details>`;
}
function map(){setBody('Una ciudad, muchas vidas','DIRECTORIO · SELECCIONÁ UN DESTINO',`<p class="muted">Elegí un destino para caminar hasta su puerta. Al llegar, presioná E o «Entrar». El recorrido respeta edificios y calles.</p><div class="map-list">${D.buildings.filter(b=>b.kind!=='property').map(b=>btn(esc(b.name)+'<small>Institución y actividad</small>','goto',{id:b.id})).join('')}</div><div class="section-title"><h3>Casas y negocios</h3></div><div class="map-list">${D.buildings.filter(b=>b.kind==='property').map(b=>btn(esc(b.name)+'<small>'+ (state().world.properties[b.id].ownerId===state().player.id?'Tu propiedad':'₳ '+money(state().world.properties[b.id].price))+'</small>','goto',{id:b.id})).join('')}</div>`)}
function player(){const s=state(),p=s.player;setBody('Tu ciudadano','IDENTIDAD · TRABAJO · PATRIMONIO',`<div class="grid">${card(`<div class="big">${esc(p.name)}</div><p>ID: ${esc(p.id)} · ${D.roles[p.role]}<br>Afiliación: ${partyName(p.party)}<br>Estado legal: ${p.legal==='FREE'?'Libre':p.legal}</p><small>Reputación: ${p.reputation}/100. Trabajo: ${D.jobs[p.job]?.name||'Sin empleo'}.</small><hr><p>Formación: ${p.training.map(t=>D.jobs[t]?.name||t).join(', ')||'Sin capacitaciones'}</p>`)}${card(metric('Patrimonio líquido','₳ '+money(p.money))+`<hr><p>Propiedades: ${p.properties.join(', ')||'Ninguna'}</p><small>Iniciaste con ₳ 100.000. El saldo siempre corresponde al libro de transacciones.</small>`)}</div><div class="section-title"><h3>Profesiones disponibles</h3></div><div class="map-list">${Object.entries(D.jobs).filter(([id])=>id!=='judge').map(([id,j])=>btn(j.name+'<small>'+building(j.at).name+' · ₳ '+money(j.pay)+'/turno</small>','goto',{id:j.at})).join('')}</div><details><summary>Mis movimientos</summary>${ledgerTable(s.ledger.filter(t=>t.from===p.id||t.to===p.id).slice(0,40))}</details><details><summary class="danger">Conflictos y consecuencias</summary><p>Un daño material inicia una causa con evidencia insuficiente para condenar. Una agresión tiene testigos y puede terminar en cárcel. No hay violencia gráfica.</p>${btn('Cometer daño material','command',{type:'CRIME',args:{crime:'damage'}},'danger small')} ${btn('Cometer agresión','command',{type:'CRIME',args:{crime:'assault'}},'danger small')}</details>`)}
function newsPanel(){setBody('La voz del Plata','CRÓNICA DE TU PARTIDA',state().news.map(n=>card(`<small class="gold">DÍA ${n.day} · ${esc(n.category.toUpperCase())}</small><h3 style="margin-top:8px">${esc(n.title)}</h3><p>${esc(n.body)}</p>`)).join('<div style="height:10px"></div>'))}
function phone(){setBody('Tu teléfono','SERVICIOS DE LA REPÚBLICA',`<div class="phone-apps">${[['government','◈','Gobierno'],['map','⌖','Mapa'],['laws','▤','Constitución'],['news','▧','Noticias'],['economy','↗','Estadísticas'],['politics','⚑','Elecciones'],['player','◎','Mi perfil'],['inventory','▣','Inventario'],['contacts','☏','Contactos'],['messages','✉','Mensajes']].map(([id,icon,label])=>btn(`<span>${icon}</span>${label}`,'open',{page:id})).join('')}</div>`)}
function contacts(){setBody('Contactos de la ciudad','DIRECTORIO INSTITUCIONAL',D.buildings.filter(b=>!['property','plaza','pitch'].includes(b.kind)).map(b=>`<div class="product"><div class="info"><strong>${b.name}</strong><small>Atención presencial · Distrito del Plata</small></div>${btn('Ir','goto',{id:b.id},'small')}</div>`).join(''))}
function messages(){setBody('Buzón ciudadano','NOTIFICACIONES DE INSTITUCIONES',state().news.filter(n=>['congreso','justicia','elecciones'].includes(n.category)).slice(0,20).map(n=>`<div class="message"><strong>${esc(n.title)}</strong><br>${esc(n.body)}<br><small>Día ${n.day}</small></div>`).join('')||'<div class="empty">Todavía no recibiste comunicaciones institucionales.</div>')}
function savePanel(){if(online){setBody('Tu partida online','IDENTIDAD Y RECONEXIÓN',`<p>La sala vive en el servidor. Este navegador conserva tu credencial de reconexión durante la sesión. No compartas esa credencial ni importes partidas locales.</p><p>Sala: <strong>${esc(engine.identity?.room||'Sin conexión')}</strong>. Para otra persona, compartí la dirección del juego y este código.</p><p>La recuperación después de reiniciar el servidor depende de que el alojamiento tenga un volumen persistente configurado.</p>${btn('Volver a conectar','netresume',{},'primary')} ${btn('Salir de esta sala','netleave',{},'danger')}`);return;}let exists=false;try{exists=!!localStorage.getItem('argentum2d-save')}catch{}setBody('Tu historia continúa','GUARDADO COMPLETO · FORMATO JSON',`<div class="grid">${card(`<h3>En este navegador</h3><p>Guarda ciudadano, dinero, inventarios, propiedades, leyes, Congreso, gobierno, economía, causas, eventos y calendario.</p><div class="row wrap">${btn('Guardar ahora','save',{},'primary')}${exists?btn('Cargar guardado','load'):''}</div><small style="display:block;margin-top:12px">Algunos navegadores limitan el almacenamiento de archivos locales. Conservá también una exportación.</small>`)}${card(`<h3>Una copia que podés llevarte</h3><p>Exportá tu partida para recuperarla en otro navegador o equipo. El archivo se valida antes de reemplazar la partida actual.</p><div class="row wrap">${btn('Exportar partida','export',{},'primary')}${btn('Importar JSON','import')}</div>`)}</div><div class="section-title"><h3>Preferencias</h3></div>${btn(state().settings.sound?'Sonido: activado':'Sonido: desactivado','sound')}<hr>${btn('Crear otra partida','newconfirm',{},'danger')}`)}
function welcome(){if(online)return onlineWelcome();const s=state(),players=Object.values(s.players);setBody('La primera alianza','LOBBY POLÍTICO · DOS PERSONAS POR PARTIDO',`<div class="hint">Prueba local: varias personas pueden alternar controles en este equipo; los rivales pueden ser bots. No hay conexión online. Nadie comienza con el cargo de Presidente o Juez.</div><div class="grid" style="margin-top:18px">${card(`<h3>Participantes locales</h3>${players.map(p=>`<div class="row between" style="margin:8px 0"><span>${esc(p.name)}</span><small>${p.isBot?'BOT':'LOCAL'} · ${p.party?'Asignado':'Sin partido'}</small>${p.id!==s.session.hostId?btn('×','command',{type:'LOBBY_REMOVE',args:{id:p.id}},'small'):''}</div>`).join('')}<hr><label>Nuevo participante</label><input id="newParticipant" placeholder="Nombre del compañero"><div class="row wrap" style="margin-top:10px">${btn('Agregar jugador','addlocal',{},'small')}${btn('Agregar fórmula rival con bots','command',{type:'LOBBY_BOTS'},'small')}</div>`)}${card(`<h3>Crear partido</h3><label>Nombre</label><input id="newParty" placeholder="Partido del Plata"><div class="grid" style="margin-top:8px"><div><label>Sigla</label><input id="newShort" maxlength="5" value="PP"></div><div><label>Color</label><input id="newColor" type="color" value="#79bfba"></div></div><details><summary>Plataforma de seis dimensiones</summary>${['Mercado','Estado','Seguridad','Libertades','Instituciones','Política social'].map((name,i)=>`<label>${name}<input id="lobbyIdeology${i}" type="range" min="0" max="100" value="50"></label>`).join('')}</details>${btn('Crear partido incompleto','createlobby',{},'primary')}`)}</div><div class="section-title"><h3>Fórmulas electorales</h3><small>Dos personas distintas, dos candidaturas</small></div><div class="grid">${s.politics.parties.map(p=>card(`<div class="row between"><h3 style="color:${p.color}">${esc(p.short)} · ${esc(p.name)}</h3><span class="tag">${p.ready?'READY':ArgentumLobby.ready(p)?'COMPLETO':'INCOMPLETO'}</span></div>${[['president','Candidato a Presidente'],['judge','Candidato a Juez']].map(([slot,title])=>`<label>${title}<select data-party="${p.id}" data-slot="${slot}"><option value="">VACANTE</option>${players.map(a=>`<option value="${a.id}" ${p.candidates[slot]===a.id?'selected':''}>${esc(a.name)}${a.isBot?' · bot':''}</option>`).join('')}</select></label>`).join('')}${btn(p.ready?'Retirar READY':'Confirmar READY','command',{type:'LOBBY_READY',args:{party:p.id}},'small')} ${btn('Eliminar fórmula','command',{type:'LOBBY_DELETE_PARTY',args:{id:p.id}},'small')}`)).join('')||'<div class="empty">Todavía no hay partidos. Creá uno o prepará una sala de prueba.</div>'}</div><details><summary>Reglas de la partida y nombre del anfitrión</summary><div class="grid"><div><label>Tu nombre</label><input id="hostName" value="${esc(s.players[s.session.hostId].name)}">${btn('Actualizar nombre','renamehost',{},'small')}</div><div><label>Bancas simuladas (5–100)</label><input id="seatCount" type="number" value="${s.session.seatCount}" min="5" max="100"></div><div><label>Días de campaña inicial (3–30)</label><input id="campaignDays" type="number" value="${s.session.campaignDays}" min="3" max="30"></div><div><label>Duración del mandato (30–180)</label><input id="termLength" type="number" value="${s.politics.constitution.termLength}" min="30" max="180"></div></div>${btn('Aplicar reglas','lobbyconfig',{},'small')}</details><div class="row wrap" style="margin-top:20px">${btn('Cerrar lobby y comenzar campaña','start',{},'primary')}${s.politics.parties.length===0&&players.length===1?btn('Preparar prueba de 6 participantes','demolobby'):''}${btn('Cargar partida','load',{},'small')}${btn('Importar JSON','import',{},'small')}</div>`,'Inicio permitido únicamente con todas las fórmulas completas y READY. La primera elección ocurre después de la campaña.')}
function ballotPanel(){const s=state();setBody('La urna de la República','UN PARTICIPANTE · UN VOTO',`<p>Fase: ${s.session.phase==='BALLOT'?'URNAS ABIERTAS':'URNAS CERRADAS'}. El escrutinio cierra el día ${s.politics.nextElection}.</p>${s.politics.ballots[s.player.id]?'<div class="message">Tu voto ya fue registrado. No podés votar dos veces.</div>':`<div class="grid">${s.politics.parties.map(p=>card(`<h3>${esc(p.name)}</h3><p>Presidente: ${esc(s.players[p.candidates.president].name)}<br>Juez: ${esc(s.players[p.candidates.judge].name)}</p>${btn('Votar esta fórmula','command',{type:'BALLOT',args:{party:p.id}},'primary')}`)).join('')}</div>`}${btn('Volver al mundo','close',{},'small')}`)}
function footballPanel(){const f=state().football;setBody('El Potrero · fútbol físico','PELOTA · PASE · REMATE · GOL',`<p>Entrás a una cancha con pelota física, rebotes y arcos. Movete con WASD, corré con Shift, apuntá con el mouse y rematá con Espacio. Q da un pase corto. La pelota se conduce por proximidad.</p><div class="row wrap">${btn('Práctica libre · 120 s','footballstart',{mode:'practice'},'primary')}${btn('Partido con bots · 120 s','footballstart',{mode:'match'})}</div><hr><p>Marcador actual: A ${f.score[0]} – ${f.score[1]} B. La puerta de salida está abajo, fuera del campo.</p>`)}
function campaignPanel(){setBody('La campaña se vive en la ciudad','ACTO · DEBATE · PROPUESTA',`<p>Tu presencia en este punto público permite una acción de campaña. Cuesta ₳ 1.500, consume energía y modifica el alcance de tu partido. Una acción por ciudadano y día.</p>${btn('Hablar ante los vecinos','command',{type:'CAMPAIGN'},'primary')} ${btn('Ver encuestas','open',{page:'politics'})} ${btn('Promesas de campaña','open',{page:'government'})}`)}
function help(){setBody('Aprender viviendo','GUÍA BREVE',`<div class="grid">${card(`<h3>La primera ley</h3><ol><li>Completá el lobby, hacé campaña y votá. Después de la elección, andá al Congreso.</li><li>Entrá con E, recorré el hall y abrí la puerta del recinto. Acercate al atril.</li><li>Presentá impuesto al consumo al 25%.</li><li>Observá los bloques. Podés modificar el texto.</li><li>Avanzá hasta la votación. Las bancas sistémicas votan según partido y texto.</li><li>Esperá al Ejecutivo o promulgá si sos Presidente.</li><li>Mirá precios, recaudación y opinión al avanzar días.</li></ol>`)}${card(`<h3>Cómo moverte</h3><p><strong>WASD / flechas:</strong> caminar.<br><strong>Clic en el mapa:</strong> seguir un recorrido.<br><strong>E:</strong> interactuar con la puerta u objeto cercano.<br><strong>Shift:</strong> correr.<br><strong>Espacio / Q:</strong> remate / pase.<br><strong>Clic / R:</strong> atacar / recargar.<br><strong>I:</strong> inventario.<br><strong>P:</strong> teléfono.<br><strong>1–5:</strong> consumir producto.<br><strong>Esc:</strong> cerrar panel.<br><strong>+ / − en mapa:</strong> zoom.</p><small>En online, los paneles no pausan la sala. El anfitrión controla la velocidad del reloj compartido.</small>`)}${card(`<h3>Economía cotidiana</h3><p>En el mercado conseguís empleo, comprás comida y agua. Una casa cuesta entre ₳ 48.000 y ₳ 65.000. Reponé su local, abrilo y avanzá días para vender. Retirá las ganancias de su caja.</p>`)}${card(`<h3>Justicia y servicios</h3><p>Un robo al mercado activa investigación, detención, juicio y cárcel. La liberación es automática al cumplir la pena. El hospital trata la salud; el cuartel capacita bomberos. Los incendios requieren equipo.</p><small>Las profesiones y los procedimientos son simplificaciones de juego.</small>`)}</div><div class="section-title"><h3>Alcance de esta edición</h3></div><p class="muted">Incluye salas online con jugadores reales y bots opcionales de prueba. No incluye reforma constitucional, ministros ni conducción de vehículos. El fútbol tiene pelota, bots y marcador; el combate genera daño y causas. La población económica es agregada.</p>`)}
function government(){
 const s=state(),g=s.governance||{measures:[],promises:[],budget:{byArea:{},totalCommitted:0},credibility:{}},pres=s.politics.president.id===s.player.id;
 const labels={IMPLEMENTING:'En implementación',ACTIVE:'En servicio',COMPLETED:'Finalizada',CAMPAIGN:'Compromiso electoral',IN_PROGRESS:'En proceso',FULFILLED:'Cumplida',ABANDONED:'Abandonada',EXPIRED:'Incumplida al vencer el plazo',BLOCKED_CONGRESS:'Rechazada por el Congreso',BLOCKED_EXECUTIVE:'Bloqueada por veto',NOT_ELECTED:'Candidatura no electa'};
 let body=`<p>Las medidas se ejecutan desde el escritorio presidencial. Los compromisos se registran junto al micrófono de campaña y se cumplen mediante leyes vigentes.</p><div class="row wrap">${btn('Ir al Congreso','goto',{id:'congress'})}${btn('Ir a la plaza','goto',{id:'plaza'})}${btn('Ver proyectos','open',{page:'congress'})}</div>`+tabs([['projects','Medidas'],['promises','Promesas'],['budget','Ejecución presupuestaria']]);
 if(tab==='budget')body+=card(`<h3>Tesoro disponible: ₳ ${money(s.accounts.treasury)}</h3><p>Contratación acumulada de medidas: ₳ ${money(g.budget.totalCommitted)}. Estos pagos ya están incluidos en el gasto del día de contratación; no se descuentan dos veces.</p><table><tr><th>Área</th><th>Pagado acumulado</th></tr>${Object.entries(g.budget.byArea).map(([k,v])=>`<tr><td>${esc(k)}</td><td>₳ ${money(v)}</td></tr>`).join('')}</table><small>Este registro cubre las medidas ejecutivas. El gasto diario general se consulta en Economía.</small>`);
 else if(tab==='promises'){
  const candidate=s.politics.parties.find(p=>p.id===s.player.party)?.candidates.president===s.player.id;
  if(s.session.phase==='CAMPAIGN'&&candidate)body+=card(`<h3>Registrar compromiso público</h3><label>Instrumento<select id="promiseKey">${Object.entries(D.laws).map(([key,d])=>`<option value="${key}">${esc(d.name)} · ${d.min}–${d.max}${d.unit}</option>`).join('')}</select></label><label>Valor objetivo en la unidad indicada<input id="promiseValue" type="number" value="22"></label><p>Máximo cinco compromisos por campaña. El objetivo no se modifica después de registrarlo.</p>${btn('Registrar junto al micrófono','promisecreate',{},'primary')}`);
  if(!g.promises.length)body+='<div class="empty">Todavía no se registraron compromisos.</div>';
  for(const p of g.promises){const mine=p.author===s.player.id,compatible=s.politics.bills.filter(b=>b.author===p.author&&b.key===p.key&&Math.abs(b.value-p.value)<.00001&&!['REJECTED','VETOED'].includes(b.status));body+=card(`<span class="tag">${labels[p.status]||esc(p.status)}</span><h3>${esc(p.title)}</h3><p>${partyName(p.party)} · campaña ${p.cycle+1}${p.dueDay?' · plazo: día '+p.dueDay:''}</p><small>Credibilidad del partido: ${(g.credibility[p.party]||0).toFixed(1)} · proyecto vinculado: ${p.billId||'ninguno'}</small>${mine&&pres&&['IN_PROGRESS','BLOCKED_CONGRESS','BLOCKED_EXECUTIVE'].includes(p.status)?`<div class="actions">${!p.billId||p.status.startsWith('BLOCKED')?compatible.map(b=>btn('Vincular exp. '+b.id,'command',{type:'PROMISE_LINK',args:{id:p.id,billId:b.id}},'small')).join(''):''}${btn('Abandonar compromiso…','promiseabandon',{id:p.id},'danger')}</div>`:''}<details><summary>Historial público</summary>${p.history.map(h=>`<p>Día ${h.day}: ${labels[h.status]||({'BILL_LINKED':'Proyecto vinculado'})[h.status]||esc(h.status)}${h.billId?' · exp. '+h.billId:''}</p>`).join('')}</details>`)}
 }else{
  body+='<div class="grid">'+Object.entries(ArgentumGovernance.definitions).map(([id,d])=>card(`<small>${d.category}</small><h3>${d.name}</h3><p>${d.description}</p><p>₳ ${money(d.budgetCost)} · implementación: ${d.implementationTime} días · servicio: ${d.duration} días.</p><small>Alcance: ${d.affectedGroups.join(', ')}. Facultad ejecutiva; no modifica impuestos.</small><div style="margin-top:12px">${pres?btn('Evaluar medida','measurepreview',{id},'primary'):'Solo el Presidente electo puede contratar.'}</div>`)).join('')+'</div>';
  body+='<h3>Medidas contratadas</h3>'+(g.measures.length?g.measures.map(m=>card(`<strong>${ArgentumGovernance.definitions[m.policyId]?.name||esc(m.policyId)}</strong><p>${labels[m.status]} · ₳ ${money(m.cost)} · puesta en servicio: día ${m.readyDay} · finaliza: día ${m.endDay}</p>`)).join(''):'<p class="muted">Sin medidas contratadas.</p>');
 }
 setBody('Gobierno y compromisos','DECISIONES · RECURSOS · CONSECUENCIAS',body);
}
function measurePreview(a){const d=ArgentumGovernance.definitions[a.id];if(!d)return;const s=state();setBody(d.name,'EVALUACIÓN PREVIA',`<p>${d.description}</p><p>Costo inmediato: <strong>₳ ${money(d.budgetCost)}</strong>. Tesoro después de contratar: ₳ ${money(s.accounts.treasury-d.budgetCost)}.</p><p>No hay efecto inmediato. Entra en servicio el día ${s.time.day+d.implementationTime} por ${d.duration} días. Requiere Presidente electo libre junto al escritorio presidencial y fondos suficientes.</p><p>La opinión responde a las consecuencias del servicio y del gasto.</p>${btn('Confirmar contratación','command',{type:'GOVERNMENT_MEASURE',args:{id:a.id}},'primary')}${btn('Volver','open',{page:'government'})}`)}

function renderPanel(){const views={government,welcome,ballot:ballotPanel,football:footballPanel,campaign:campaignPanel,congress,economy,society,politics,laws,inventory,map,player,news:newsPanel,phone,contacts,messages,save:savePanel,help,building:buildingPanel};views[panel]?.()}
function enter(id){const b=id?building(id):nearby();if(!b)return toast('Acercate a la puerta.',true);if(perform('ENTER',{id:b.id}).ok){world.route=[];close();renderHUD();toast('Entraste. Movete con WASD y usá E junto a puertas y objetos.')}}
function go(id){if(state().player.legal!=='FREE')return toast('No podés abandonar la custodia.',true);if(state().player.inside)return toast('Primero caminá a la puerta de salida del interior.',true);close();if(world.go(id)){world.follow=true;toast('Caminando a '+building(id).name)}else toast('No se encontró recorrido. Acercate a la calle.',true);renderHUD()}
function interact(){const s=state(),p=s.player;if(p.seated){perform('SIT');return}if(!p.inside){const npc=ArgentumPhysical.actorList(s,null).find(a=>a.id!==p.id&&Math.hypot(a.x-p.x,a.y-p.y)<65);if(nearby())enter();else if(npc){perform('TALK',{id:npc.id});toast(s.world.lastConversation?.text||'Conversación registrada.')}else enter();return}const o=ArgentumInteriors.nearest(s);if(!o){const npc=ArgentumPhysical.actorList(s,p.inside).find(a=>a.id!==p.id&&Math.hypot(a.x-p.x,a.y-p.y)<75);if(npc){const r=perform('TALK',{id:npc.id});if(r.ok)toast(state().world.lastConversation.text)}else toast('Acercate a una puerta, objeto o personaje.');return}if(o.kind==='exit'){if(perform('EXIT').ok)close()}else if(o.kind==='door')perform('DOOR',{id:o.id});else if(o.kind==='seat')perform('SIT',{id:o.id},'Te sentaste. E para levantarte.');else if(o.kind==='shelf')perform('CART_ADD',{id:o.id},'Producto agregado al carrito. Pagá en la caja.');else if(o.kind==='armory'){const r=perform('TEST_KIT',{},'Equipo de prueba en inventario.');if(r.ok)open('inventory')}else if(o.kind==='ballot')open('ballot');else if(o.kind==='football')open('football');else if(o.kind==='campaign')open('campaign');else if(o.kind==='bed'){const r=perform('REST',{},'Descanso completado.');if(!r.ok&&p.inside==='hospital')open('building')}else if(o.kind==='info')open('help');else open('building');}
const actions={measurepreview:measurePreview,promisecreate:()=>{const key=$('promiseKey').value;perform('PROMISE_CREATE',{key,value:Number($('promiseValue').value)/D.laws[key].factor},'Compromiso registrado.')},promiseabandon:a=>setBody('Abandonar compromiso','DECISIÓN PÚBLICA',`<p>El abandono quedará registrado y reducirá la credibilidad del partido.</p>${btn('Confirmar abandono','command',{type:'PROMISE_ABANDON',args:a},'danger')}${btn('Volver','open',{page:'government'})}`),interact,lobbyconfig:()=>perform('LOBBY_CONFIG',{seats:Number($('seatCount').value),campaignDays:Number($('campaignDays').value),termLength:Number($('termLength').value)}),renamehost:()=>perform('LOBBY_RENAME',{id:state().session.hostId,name:$('hostName').value}),routeexit:()=>{const r=ArgentumInteriors.get(state().player.inside);if(r){close();world.walkTo(r.exit.x+r.exit.w/2,r.exit.y-18)}},addlocal:()=>perform('LOBBY_ADD',{name:$('newParticipant').value}),createlobby:()=>perform('LOBBY_CREATE',{name:$('newParty').value,short:$('newShort').value,color:$('newColor').value,ideology:Array.from({length:6},(_,i)=>Number($('lobbyIdeology'+i).value)/100)}),demolobby:()=>{let r=engine.dispatch('LOBBY_CREATE',{name:'Acuerdo del Plata',short:'AP',color:'#7fc6bb',ideology:[.5,.5,.5,.8,.9,.6]});if(!r.ok)return toast(r.error,true);engine.dispatch('LOBBY_ADD',{name:'Compañero local'});let ps=state().politics.parties[0],other=Object.keys(state().players).find(id=>id!=='player');engine.dispatch('LOBBY_ASSIGN',{party:ps.id,slot:'president',player:'player'});engine.dispatch('LOBBY_ASSIGN',{party:ps.id,slot:'judge',player:other});engine.dispatch('LOBBY_READY',{party:ps.id});engine.dispatch('LOBBY_BOTS');engine.dispatch('LOBBY_BOTS');renderHUD();renderPanel()},footballstart:a=>{if(perform('FOOTBALL_START',a).ok)close()},equip:a=>perform('EQUIP',a,'Equipo actualizado.'),open:a=>open(a.page),close,tab:a=>{tab=a.tab;renderPanel()},scenario:a=>{scenario=a.scenario;document.querySelectorAll('.scenario').forEach(b=>b.classList.toggle('chosen',JSON.parse(b.dataset.args).scenario===scenario))},start:()=>{const r=perform('START');if(r.ok){started=true;world.route=[];world.zoom=1;close();renderHUD();toast('La campaña comenzó. Los cargos se definen en las urnas.')}},enter:a=>enter(a.id),exit:()=>{if(perform('EXIT').ok)close()},goto:a=>go(a.id),speed:a=>{if(online)return perform('SET_SPEED',a);state().time.speed=a.speed;timer=0;renderHUD()},advance:a=>online?toast('El calendario avanza con el reloj del servidor. Solo el anfitrión puede pausarlo o cambiar su velocidad.'):perform('ADVANCE',a,'Calendario actualizado: jornada '+(state().time.day+a.days)),command:a=>perform(a.type,a.args||{},'Acción registrada.'),use:a=>perform('USE',a,'Producto utilizado.'),propose:()=>{const key=$('lawKey').value,def=D.laws[key];const r=perform('PROPOSE',{key,value:Number($('lawValue').value)/def.factor,title:$('billTitle').value},'Proyecto presentado.');if(r.ok){tab='projects';renderPanel()}},amend:a=>{const b=state().politics.bills.find(b=>b.id===a.id);perform('AMEND',{id:a.id,value:Number($('amend-'+a.id).value)/D.laws[b.key].factor},'Texto actualizado; los bloques reevaluaron su posición.')},compromise:a=>{const b=state().politics.bills.find(b=>b.id===a.id),p=party(a.party),def=D.laws[b.key],value=Math.round(((b.value+p[b.key])/2)*def.factor/def.step)*def.step/def.factor;perform('AMEND',{id:a.id,value},'Propuesta acercada a la preferencia del bloque.')},package:a=>{const b=state().politics.bills.find(b=>b.id===a.id);perform('AMEND',{id:a.id,value:b.value,packageHealth:b.packageHealth?null:1.2},'Artículo sanitario actualizado.')},createparty:()=>{const ideology=['economy','state','security','liberty','institutions','social'].map(k=>Number($('ideology-'+k).value)/100),name=$('partyName').value;const r=perform('CREATE_PARTY',{name,ideology},'Partido creado. Tu candidatura está inscripta.');if(r.ok){tab='parties';renderPanel()}},business:a=>perform('BUSINESS',{...a,markup:Number($('markup').value)},'Configuración del local actualizada.'),zoomin:()=>{world.zoom=Math.min(2.8,world.zoom+.3);world.follow=true},zoomout:()=>world.zoom=Math.max(.8,world.zoom-.3),center:()=>{world.zoom=1.6;world.follow=true},save:()=>{try{localStorage.setItem('argentum2d-save',engine.save());toast('Partida guardada en este navegador.');renderPanel()}catch{toast('El navegador no permite guardado local. Exportá la partida.',true)}},load:()=>{let data;try{data=localStorage.getItem('argentum2d-save')}catch{}if(!data)return toast('No hay un guardado en este navegador.',true);const r=engine.load(data);if(r.ok){started=state().session.phase!=='LOBBY';world.route=[];if(started)close();else{panel='welcome';welcome()}renderHUD();toast('Partida recuperada.')}else toast(r.error,true)},export:()=>{const blob=new Blob([engine.save()],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='ARGENTUM-partida-dia-'+state().time.day+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Partida exportada.')},import:()=>$('fileInput').click(),sound:()=>{state().settings.sound=!state().settings.sound;toast(state().settings.sound?'Sonidos activados.':'Sonidos desactivados.');renderPanel()},newconfirm:()=>setBody('¿Empezar otra historia?','LA PARTIDA ACTUAL SE REEMPLAZARÁ',`<p>Exportá o guardá tu partida si querés conservarla antes de iniciar otra.</p><div class="row">${btn('Exportar partida actual','export',{},'primary')}${btn('Elegir nuevo ciudadano','newgame')}${btn('Cancelar','open',{page:'save'})}`),newgame:()=>{engine=new A.Engine(A.newGame('Hernán'));started=false;panel='welcome';welcome();renderHUD()}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.open){open(b.dataset.open);return}if(b.dataset.action){try{actions[b.dataset.action]?.(JSON.parse(b.dataset.args||'{}'))}catch(error){console.error(error);toast('No se pudo completar la acción: '+error.message,true)}}});
document.addEventListener('change',e=>{if(e.target.id==='actorSelect'){if(online)return;engine.switchActor(e.target.value);world.route=[];world.keys.clear();if(panel&&panel!=='welcome')close();renderHUD();return}if(e.target.dataset.party){perform('LOBBY_ASSIGN',{party:e.target.dataset.party,slot:e.target.dataset.slot,player:e.target.value||null});return}if(e.target.id==='lawKey'){const key=e.target.value,d=D.laws[key];$('lawValue').min=d.min;$('lawValue').max=d.max;$('lawValue').step=d.step;$('lawValue').value=Math.round(state().policy[key]*d.factor);$('valueLabel').textContent=`Nuevo valor · ${d.min} a ${d.max}${d.unit}`;$('lawDescription').textContent=d.description;$('currentValue').textContent=Math.round(state().policy[key]*d.factor)+d.unit;$('billTitle').value='Reforma de '+d.name.toLowerCase()}});
$('fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const r=engine.load(await file.text());if(r.ok){started=state().session.phase!=='LOBBY';world.route=[];if(started)close();else{panel='welcome';welcome()}renderHUD();toast('Partida importada.')}else toast(r.error,true);e.target.value=''});
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='tab'&&panel){const focusable=[...$('overlay').querySelectorAll('button,input,select,summary')].filter(x=>x.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}return}if(k==='escape'){close();return}if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(!started)return;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='e'){if(!panel)interact();return}if(k==='r'){perform('RELOAD');return}if(k===' '||k==='q'){if(!panel&&state().player.inside==='pitch'){perform('KICK',{...(world.aim||{x:1080,y:340}),pass:k==='q'});return}}if(k==='i'){panel==='inventory'?close():open('inventory');return}if(k==='p'){panel==='phone'?close():open('phone');return}if(/^[1-5]$/.test(k)){actions.use({id:D.products[Number(k)-1].id});return}if(!panel)world.keys.add(k)});
document.addEventListener('keyup',e=>world.keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>world.keys.clear());
function frame(t){const dt=last?t-last:0;last=t;
 if(online){engine.intent=null;if(started&&!panel&&engine.connected)world.tick(dt,(type,args)=>engine.dispatch(type,args));engine.flushInput(t);
  // Interpolate only for rendering. Gameplay and proximity always use server positions.
  const saved=[];for(const [id,p] of Object.entries(state().players)){saved.push([p,p.x,p.y]);Object.assign(p,engine.visual(id,t));}
  try{world.render(t)}finally{for(const [p,x,y]of saved){p.x=x;p.y=y}}
 }else{if(started&&!panel){world.tick(dt,(type,args)=>engine.dispatch(type,args));const physicsResult=engine.dispatch('PHYSICS',{dt:Math.min(.05,Math.max(.001,dt/1000))});if(!physicsResult.ok&&!world.physicsError){world.physicsError=true;console.error(physicsResult.error)}if(state().time.speed){timer+=Math.min(dt,100)*state().time.speed;if(timer>=12000){timer=0;perform('ADVANCE',{days:1});try{localStorage.setItem('argentum2d-auto',engine.save())}catch{}}}}world.render(t);}
 if(t-lastHud>450){renderHUD();lastHud=t}requestAnimationFrame(frame)
}
function onlineWelcome(){
 const s=state(),me=s.player,host=me.id===s.session.hostId;
 if(!engine.connected){const cred=engine.credentials();setBody('Una república entre personas','ARGENTUM 2D · MULTIJUGADOR ONLINE',`<p>Creá una sala y compartí el código. Cada persona entra desde su navegador y controla a su ciudadano.</p><div class="grid"><div>${card(`<label>Tu nombre<input id="netName" maxlength="32" value="Ciudadano"></label><label>Servidor WebSocket<input id="netEndpoint" value="${esc(cred?.endpoint||(location.protocol==='file:'?'ws://localhost:3000/ws':(location.protocol==='https:'?'wss:':'ws:')+'//'+location.host+'/ws'))}"></label><label><input id="netTest" type="checkbox"> Sala de prueba: permitir bots y equipo de combate</label>${btn('Crear partida','netcreate',{},'primary')}`)}</div><div>${card(`<label>Código de sala<input id="netRoom" maxlength="10" placeholder="Código de 10 caracteres"></label>${btn('Unirse a partida','netjoin',{},'primary')} ${cred?btn('Reconectar a mi ciudadano','netresume'):''}<p>El micrófono se activa únicamente cuando lo elijas, después de entrar.</p>`)}</div></div>${location.protocol==='file:'?'<p>Para servir el juego y su red, ejecutá npm start y abrí http://localhost:3000. La voz requiere HTTPS o localhost.</p>':''}`,engine.status);return;}
 const players=Object.values(s.players);
 setBody('La primera alianza','SALA '+esc(engine.identity.room)+' · '+players.filter(p=>p.connected).length+'/'+players.length+' CONECTADOS',`<div class="message">Compartí esta dirección y el código <strong>${esc(engine.identity.room)}</strong>. Cada persona elige su candidatura y confirma su READY. ${s.session.testMode?'Sala de prueba con bots habilitados.':''}</div><div class="grid">${card(`<h3>Participantes</h3>${players.map(p=>`<div class="row between"><span>${esc(p.name)}${p.id===me.id?' · vos':''}</span><small>${p.isBot?'BOT':p.connected?'CONECTADO':'DESCONECTADO'} · ${p.party?'con partido':'sin partido'}</small>${host&&p.id!==me.id&&(!p.connected||p.isBot)?btn('Retirar','command',{type:'LOBBY_REMOVE',args:{id:p.id}},'small'):''}</div>`).join('')}${host&&s.session.testMode?btn('Agregar partido de bots','command',{type:'LOBBY_BOTS'},'small'):''}`)}${card(`<h3>Crear partido</h3><label>Nombre<input id="newParty" maxlength="40" placeholder="Acuerdo del Plata"></label><div class="grid"><label>Sigla<input id="newShort" maxlength="5" value="AP"></label><label>Color<input id="newColor" type="color" value="#79bfba"></label></div><details><summary>Plataforma política</summary>${['Mercado','Estado','Seguridad','Libertades','Instituciones','Política social'].map((name,i)=>`<label>${name}<input id="lobbyIdeology${i}" type="range" min="0" max="100" value="50"></label>`).join('')}</details>${btn('Crear fórmula','createlobby',{},'primary')}`)}</div><div class="grid" style="margin-top:16px">${s.politics.parties.map(p=>card(`<div class="row between"><h3 style="color:${p.color}">${esc(p.name)}</h3><span class="tag">${p.ready?'READY':'EN FORMACIÓN'}</span></div>${[['president','Presidente'],['judge','Juez']].map(([slot,title])=>`<p>${title}: <strong>${esc(s.players[p.candidates[slot]]?.name||'Vacante')}</strong> ${!p.candidates[slot]&&!me.party?btn('Ser candidato','command',{type:'LOBBY_ASSIGN',args:{party:p.id,slot,player:me.id}},'small'):p.candidates[slot]===me.id?btn('Liberar mi lugar','command',{type:'LOBBY_ASSIGN',args:{party:p.id,slot,player:null}},'small'):''}</p>`).join('')}${p.members.includes(me.id)?btn(s.session.readyPlayers?.[me.id]?'Retirar mi READY':'Confirmar mi READY','command',{type:'LOBBY_READY',args:{party:p.id}},'primary'):''}<small>Confirmaciones: ${p.members.filter(id=>s.players[id].isBot||s.session.readyPlayers?.[id]).length}/2</small>${p.members.length===0?btn('Eliminar fórmula vacía','command',{type:'LOBBY_DELETE_PARTY',args:{id:p.id}},'small'):''}`)).join('')}</div>${host?`<details><summary>Reglas de la sala</summary><div class="grid"><label>Bancas<input id="seatCount" type="number" value="${s.session.seatCount}" min="5" max="100"></label><label>Días de campaña<input id="campaignDays" type="number" value="${s.session.campaignDays}" min="3" max="30"></label><label>Días de mandato<input id="termLength" type="number" value="${s.politics.constitution.termLength}" min="30" max="180"></label></div>${btn('Aplicar reglas','lobbyconfig')}</details>${btn('Comenzar campaña compartida','start',{},'primary')}`:'<p>El anfitrión inicia cuando todas las fórmulas tengan dos candidatos conectados y ambos hayan confirmado READY.</p>'} ${btn('Salir de la sala','netleave',{},'small')}`,'La voz del lobby está disponible en el control de micrófono. Nadie recibe cargos antes de las elecciones.');
}
if(online){
 actions.netcreate=()=>engine.connect('create',{name:$('netName').value,endpoint:$('netEndpoint').value,testMode:$('netTest').checked});
 actions.netjoin=()=>engine.connect('join',{name:$('netName').value,endpoint:$('netEndpoint').value,room:$('netRoom').value.trim().toUpperCase()});
 actions.netresume=()=>{const c=engine.identity||engine.credentials();if(c)engine.connect('resume',c);else toast('No hay una sesión para recuperar.',true)};
 actions.netleave=()=>{engine.leave();started=false;panel='welcome';onlineWelcome()};
 actions.load=actions.netresume;actions.import=actions.export=actions.save=()=>toast('El servidor conserva la partida; usá Reconectar.');actions.newgame=actions.netleave;
 engine.on('error',message=>toast(message,true));
 engine.on('status',()=>{renderHUD();if(panel==='welcome'&&!engine.connected)$('dialogNote').textContent=engine.status;});
 let lobbyStamp='';
 engine.on('state',({state:s,previous})=>{
  if(s.player.inside!==previous.player.inside){world.route=[];world.keys.clear();}
  started=s.session.phase!=='LOBBY';
  if(started&&panel==='welcome'){close();toast('La campaña compartida comenzó.');}
  if(!started){panel='welcome';const stamp=JSON.stringify([s.politics.parties,Object.values(s.players).map(p=>[p.id,p.name,p.connected,p.party]),s.session.readyPlayers,s.session.seatCount,s.session.campaignDays]);if(stamp!==lobbyStamp){lobbyStamp=stamp;onlineWelcome();}}
  else if(panel&&(s.time.day!==previous.time.day||s.seq!==previous.seq)&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))renderPanel();
  if(s.session.serverFault)toast('La simulación fue pausada por un error del servidor: '+s.session.serverFault,true);
 });
 window.ARGENTUM_VOICE=new ArgentumVoice(engine);
 setInterval(()=>{if(engine.connected)engine.send({kind:'ping',at:Date.now()})},5000);
}
window.ARGENTUM_APP={get engine(){return engine},world,open,close,perform,get panel(){return panel}};
$('city').addEventListener('mousemove',e=>{const r=$('city').getBoundingClientRect();world.aim=world.toWorld(e.clientX-r.left,e.clientY-r.top)});world.clickAction=point=>{if(state().player.equipped&&!panel){perform('ATTACK',point);return true}return false};renderHUD();open('welcome');requestAnimationFrame(frame);
})();
